import 'package:equatable/equatable.dart';

import 'day_key.dart';
import 'task_list.dart';

/// One thing to do on one day.
///
/// A task either stands alone (added by hand) or is a step generated by a
/// routine for that day; [routineId] is what tells the two apart, and only
/// routine steps feed the daily quest.
class Task extends Equatable {
  const Task({
    required this.id,
    required this.day,
    required this.title,
    required this.list,
    required this.xpReward,
    required this.whenLabel,
    required this.repeatLabel,
    required this.note,
    required this.sortIndex,
    this.routineId,
    this.isDone = false,
    this.completedAt,
  });

  final int id;
  final DayKey day;
  final String title;
  final TaskList list;
  final int xpReward;
  final String whenLabel;
  final String repeatLabel;
  final String note;
  final int sortIndex;
  final String? routineId;
  final bool isDone;
  final DateTime? completedAt;

  bool get isRoutineStep => routineId != null;

  Task copyWith({
    DayKey? day,
    String? title,
    bool? isDone,
    DateTime? completedAt,
    bool clearCompletedAt = false,
  }) => Task(
    id: id,
    day: day ?? this.day,
    title: title ?? this.title,
    list: list,
    xpReward: xpReward,
    whenLabel: whenLabel,
    repeatLabel: repeatLabel,
    note: note,
    sortIndex: sortIndex,
    routineId: routineId,
    isDone: isDone ?? this.isDone,
    completedAt: clearCompletedAt ? null : (completedAt ?? this.completedAt),
  );

  @override
  List<Object?> get props => <Object?>[
    id,
    day.value,
    title,
    list,
    xpReward,
    whenLabel,
    repeatLabel,
    note,
    sortIndex,
    routineId,
    isDone,
    completedAt,
  ];
}
